window.AUTH=window.AUTH||{};window.AUTH["21-499"]={"d":"21-499","id":"2021/21-499","n":"Vega v. Tekoh","briefs":[{"k":"petitioner","label":"Brief of petitioner Carlos Vega","date":"2022-02-28","url":"https://www.supremecourt.gov/DocketPDF/21/21-499/215133/20220228131914330_2022-02-28%20SCT%20No.%2021-499%20Vega%20Merits%20Brief%20with%20addendum.pdf","side":"pet","n":50},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2022-03-07","url":"https://www.supremecourt.gov/DocketPDF/21/21-499/217904/20220307182400779_21-499tsacUnitedStates.pdf","side":"us","n":67},{"k":"respondent","label":"Brief of respondent Terence B. Tekoh","date":"2022-03-30","url":"https://www.supremecourt.gov/DocketPDF/21/21-499/219794/20220330161619832_Respondents%20Brief.pdf","side":"res","n":75},{"k":"reply","label":"Reply of petitioner Carlos Vega","date":"2022-04-08","url":"https://www.supremecourt.gov/DocketPDF/21/21-499/220596/20220408123309095_2022-04-08%20No%2021-499%20Vega%20Merits%20Reply%20Brief.pdf","side":"pet","n":29}],"opinion":"https://www.supremecourt.gov/opinions/21pdf/597us1r55_8m58.pdf","tr":true,"items":[{"t":"case","label":"Angov v. Lynch","cite":"788 F.3d 893","y":2015,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/788/893/","by":{"0":"41"}},{"t":"case","label":"Ashcroft v. Iqbal","cite":"556 U.S. 662","y":2009,"id":"2008/07-1015","sc":1,"sum":"The Court found that high-ranking government officials were not liable for unconstitutional acts by subordinate officials.","sumSrc":"Oyez","by":{"0":"38","1":"17","2":"47"}},{"t":"case","label":"Blessing v. Freestone","cite":"520 U.S. 329","y":1997,"id":"1996/95-1441","sc":1,"op":1,"sum":"The Court ruled that Title IV-D of the Social Security Act does not give individuals a federal right to force a state agency to substantially comply with Title IV-D. Justice O'Connor wrote for the court that parents cannot sue merely because a state fails to be in \"substantial compliance\" with federal collection standards.","sumSrc":"Oyez","by":{"0":"31"}},{"t":"case","label":"Brecht v. Abrahamson","cite":"507 U.S. 619","y":1993,"id":"1992/91-7358","sc":1,"op":4,"sum":"Chief Justice William H. Rehnquist wrote that the \"substantial and injurious effect\" test was preferable to the \"beyond a reasonable doubt\" test in requests for habeas corpus relief. Habeas proceedings are not to be the primary avenue for resolving disputes; Rehnquist called the writ \"an extraordinary remedy\", reserved for the victims of grave injustice.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Brower v. County of Inyo","cite":"489 U.S. 593","y":1989,"id":"1988/87-248","sc":1,"sum":"The Court held that a police roadblock could constitute an illegal seizure under the Fourth Amendment.","sumSrc":"Oyez","by":{"0":"37"}},{"t":"case","label":"Caballero v. City of Concord","cite":"956 F.2d 204","y":1992,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/956/204/","by":{"0":"48"}},{"t":"case","label":"Chavez v. Martinez","cite":"538 U.S. 760","y":2003,"id":"2002/01-1444","sc":1,"op":3,"ar":13,"sum":"In a 6-3 judgment delivered by Justice Clarence Thomas, the Court held that Chavez did not deprive Martinez of his Fifth Amendment rights. Chief Justice William H. Rehnquist and Justices Sandra Day O'Connor and Antonin Scalia, joined Justice Thomas.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"passim","3":"passim"}},{"t":"case","label":"Connecticut v. Barrett","cite":"479 U.S. 523","y":1987,"id":"1986/85-899","sc":1,"op":1,"sum":"The Constitution did not require suppression of respondent's incriminating statement.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22","2":"27","3":"4"}},{"t":"case","label":"County of Los Angeles v. Mendez","cite":"137 S. Ct. 1539","y":2017,"id":"2016/16-369","sc":1,"sum":"The Court determined that the U.S. Court of Appeals for the Ninth Circuit’s provocation rule has no basis in the Fourth Amendment, and that the lower court erroneously conflated multiple Fourth Amendment violation claims.","sumSrc":"Oyez","by":{"0":"37","1":"15","2":"36,37"}},{"t":"case","label":"CSX Transportation, Inc. v. McBride","cite":"564 U.S. 685","y":2011,"id":"2010/10-235","sc":1,"sum":"The Supreme Court affirmed the lower court order in an opinion by Justice Ruth Bader Ginsburg. \"The charge proper in FELA cases, we hold, simply tracks the language Congress employed, informing juries that a defendant railroad caused or contributed to a plaintiff employee's injury if the railroad's negligence played any part in bringing about the injury,\" Ginsburg wrote for the majority.","sumSrc":"Oyez","by":{"0":"38","2":"45-46"}},{"t":"case","label":"Davis v. United States","cite":"512 U.S. 452","y":1994,"id":"1993/92-1949","sc":1,"op":1,"sum":"The Supreme Court held that, assuming Edwards applies in military proceedings, investigators do not need to cease questioning when an accused makes an ambiguous statement like “Maybe I should talk to a lawyer.” The Court noted that, while it was proper for the investigators to clarify Davis’ intentions, the Court does not require investigators to adopt that practice in future interrogations.","sumSrc":"Oyez","by":{"0":"32","2":"27"}},{"t":"case","label":"Department of Transportation v. Public Citizen","cite":"541 U.S. 752","y":2004,"id":"2003/03-358","sc":1,"sum":"The Court held that the FMCSA had no control of the trucks once the regulations were passed, and would therefore be unable to act on the findings of an EIS even if it did conduct one. Further, the Court found that the passage of the regulations was not sufficiently responsible for the increased pollution caused by the trucks to warrant an EIS.","sumSrc":"Oyez","by":{"0":"38"}},{"t":"case","label":"Dickerson v. United States","cite":"530 U.S. 428","y":2000,"id":"1999/99-5525","sc":1,"op":20,"sum":"Explaining that the Court “do[es] not hold a supervisory power over the courts of the several States”.","sumSrc":"opinion","by":{"0":"passim","1":"3, 9, 20","2":"passim","3":"1, 5, 6"}},{"t":"case","label":"Golden State Transit Corp. v. City of Los Angeles","cite":"493 U.S. 103","y":1989,"id":"1989/88-840","sc":1,"sum":"Petitioner is entitled to maintain a § 1983 action for compensatory damages.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31"}},{"t":"case","label":"Harris v. New York","cite":"401 U.S. 222","y":1971,"id":"1970/206","sc":1,"op":2,"sum":"In a 5-to-4 decision, the Court held that the Miranda decision did not mandate that evidence inadmissible against an accused in the prosecution's case must be barred for all purposes from the trial.","sumSrc":"Oyez","by":{"0":"passim","1":"10, 20, 25","2":"25"}},{"t":"case","label":"Howes v. Fields","cite":"565 U.S. 499","y":2012,"id":"2011/10-680","sc":1,"op":1,"sum":"The Court held that a prisoner, currently held in jail, did not have his Miranda rights violated when he was questioned inside the jail for a different crime.","sumSrc":"Oyez","by":{"0":"20, 44"}},{"t":"case","label":"J.D.B. v. North Carolina","cite":"564 U.S. 261","y":2011,"id":"2010/09-11121","sc":1,"op":2,"sum":"The Court ruled that courts should consider the age of a juvenile suspect in deciding whether he or she is in custody for Miranda purposes.","sumSrc":"Oyez","by":{"0":"20, 29","1":"13","3":"7"}},{"t":"case","label":"Lexmark International, Inc. v. Static Control Components, Inc.","cite":"572 U.S. 118","y":2014,"id":"2013/12-873","sc":1,"sum":"The Court held that the Lanham Act allowed any party to sue for injuries relating to false advertising, as long as the party bringing suit has an interest that falls in the zone of interest that is protected by law.","sumSrc":"Oyez","by":{"0":"38, 43","2":"46"}},{"t":"case","label":"Mapp v. Ohio","cite":"367 U.S. 643","y":1961,"id":"1960/236","sc":1,"sum":"The Court decided that evidence obtained illegally may not be used against someone in a court of law by the Fourth Amendment.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"Maryland v. Shatzer","cite":"559 U.S. 98","y":2010,"id":"2009/08-680","sc":1,"op":3,"sum":"The Court held that the ruling in Edwards v. Arizona does not allow for suppression of statements if a substantial period of time between the invoking one's Miranda rights and a second interrogation takes place.","sumSrc":"Oyez","by":{"0":"20, 32, 44"}},{"t":"case","label":"Michigan v. Harvey","cite":"494 U.S. 344","y":1990,"id":"1989/88-512","sc":1,"op":1,"sum":"A statement to police taken in violation of Jackson may be used to impeach a defendant's testimony. The Jackson rule is based on the identical \"prophylactic rule\" announced in Edwards v. Arizona, 451 U. S. 477, in the context of the Fifth Amendment privilege against selfincrimination during custodial interrogation. Moreover, Harrisv. New York, 401 U. S. 222, and subsequent cases have held that voluntary statements …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20"}},{"t":"case","label":"Michigan v. Mosley","cite":"423 U.S. 96","y":1975,"id":"1975/74-653","sc":1,"sum":"The Court held that the rights to silence and to have an attorney present during a custodial interrogation established in Miranda v. Arizona are not violated when, after a suspect invokes his right to silence and questioning ceases, the suspect is read his rights again and a sufficient amount of time passes before a second interrogation.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Michigan v. Payne","cite":"412 U.S. 47","y":1973,"id":"1972/71-1005","sc":1,"op":1,"sum":"The \"prophylactic\" due process limitations established by North Carolina v. Pearce, 395 U. S. 711, 723-726, to guard against the possibility of vindictiveness in cases -where a judge imposes a more severe sentence upon a defendant after a new trial, are not retroactively applicable to resentencing proceedings that, like the one involved in this case, occurred prior to the date of the Pearce decision. Pp. 50-57. 386 …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20, 25, 29, 30","3":"4, 6"}},{"t":"case","label":"Michigan v. Tucker","cite":"417 U.S. 433","y":1974,"id":"1973/73-482","sc":1,"op":5,"sum":"Respondent, who had been arrested for rape, was questioned by police. Before the commencement of the interrogation (which antedated this Court's decision in Miranda v. Arizona, 384 U. S. 436), respondent was advised of his right to remain silent and his right to counsel (but not of his right to the appointment of counsel if he was indigent). Respondent related an alibi that he was with a friend (Henderson), at the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18, 23, 30, 32, 35","1":"10","2":"27","3":"4, 11"}},{"t":"case","label":"Mincey v. Arizona","cite":"437 U.S. 385","y":1978,"id":"1977/77-5353","sc":1,"op":1,"sum":"The Court held that the extensive, warrantless search of Mincey’s apartment was unreasonable and unconstitutional under the Fourth and Fourteenth Amendments. Justice Stewart wrote that warrantless searches were per se unreasonable with a few specific exceptions, and rejected Arizona’s argument that the search of a homicide scene was one of these exceptions.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"Miranda v. Arizona","cite":"384 U.S. 436","y":1966,"id":"1965/759","sc":1,"op":139,"ar":52,"sum":"The Court held that law enforcement cannot use testimony given by anyone under interrogation while in custody without that person being informed of their legal rights.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"passim"}},{"t":"case","label":"Mississippi Department of Transportation v. Signal International, LLC (In re Signal International, LLC)","cite":"579 F.3d 478","y":2009,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/579/478/","by":{"0":"38"}},{"t":"case","label":"Montejo v. Louisiana","cite":"556 U.S. 778","y":2009,"id":"2008/07-1529","sc":1,"op":1,"sum":"The Court held that after the appointment of an attorney, a defendant does not necessarily need to take additional steps to accept the appointment in order to secure the protections of the Sixth Amendment.","sumSrc":"Oyez","by":{"0":"4, 20, 29, 30, 32","3":"7"}},{"t":"case","label":"New York v. Quarles","cite":"467 U.S. 649","y":1984,"id":"1983/82-1213","sc":1,"op":3,"sum":"The Court held that there is a \"public safety\" exception to the requirement that officers issue Miranda warnings to suspects. Since the police officer's request for the location of the gun was prompted by an immediate interest in assuring that it did not injure an innocent bystander or fall into the hands of a potential accomplice to Quarles, his failure to read the Miranda warning did not violate the Constitution.","sumSrc":"Oyez","by":{"0":"passim","1":"12, 13, 25","2":"25,27","3":"4, 5"}},{"t":"case","label":"Ohio v. Robinette","cite":"519 U.S. 33","y":1996,"id":"1996/95-891","sc":1,"sum":"After establishing its federal jurisdiction, despite a claim that the matter involved aspects of Ohio's Constitution, the Court held that when looking at the totality of the circumstances it may be reasonably concluded that if a defendant consents to be searched, even if not first advised that he is \"free to go,\" the ensuing search will be recognized as voluntary.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Oregon v. Elstad","cite":"470 U.S. 298","y":1985,"id":"1984/83-773","sc":1,"op":5,"sum":"In a 6-to-3 decision, the Court held that while Miranda required that unwarned admissions must be suppressed, subsequent statements, if made knowingly and voluntarily, need not be. The Court held that \". . .the mere fact that a suspect has made an unwarned admission does not warrant a presumption of compulsion.\" The Court also noted that police officers were ill-equipped to determine when \"custody\" legally begins.","sumSrc":"Oyez","by":{"0":"passim","1":"10, 14, 20, 25","2":"27","3":"1, 3, 4, 5"}},{"t":"case","label":"Paroline v. United States","cite":"572 U.S. 434","y":2014,"id":"2013/12-8561","sc":1,"sum":"The Court ruled that to recover restitution, either the government or the victim must establish a causal relationship between the defendant's conduct and the victim's harm or damages.","sumSrc":"Oyez","by":{"0":"38","1":"15","2":"37","3":"20"}},{"t":"case","label":"Page(s) Plumhoff v. Rickard","cite":"572 U.S. 765","y":2014,"id":"2013/12-1117","sc":1,"sum":"The Court held that police using deadly force to prevent a crime endangering the general public are granted qualified immunity.","sumSrc":"Oyez","by":{"0":"49"}},{"t":"case","label":"Stoot v. City of Everett","cite":"582 F.3d 910","y":2009,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/582/910/","by":{"0":"10, 42, 43, 45, 46"}},{"t":"case","label":"Townes v. City of New York","cite":"176 F.3d 138","url":"https://www.courtlistener.com/c/F.3d/176/138/","by":{"0":"31"}},{"t":"case","label":"United States v. Armstrong","cite":"517 U.S. 456","y":1996,"id":"1995/95-157","sc":1,"sum":"Announced by Chief Justice William H. Rehnquist, the Court held that in order to file selective-prosecution claims, defendants must show that the government failed to prosecute similarly situated suspects of other races. \"If the claim . . . were well founded,\" wrote Rehnquist, \"it should not have been an insuperable task to prove that persons of a different race were not prosecuted.\".","sumSrc":"Oyez","by":{"0":"41","1":"17","3":"20"}},{"t":"case","label":"United States v. Blue","cite":"384 U.S. 251","y":1966,"id":"1965/531","sc":1,"op":10,"sum":"Appellee Was inforined by the Internal Revenue Service in 1962 that he might be prosecuted criminally for violation of federal income tax laws. In 1963 jeopardy assessments were made against him, his wife, and a wholly owned corporation, and all known assets of all three were seized and tax liens recorded. Pursuant to notices giving appellee 90 days in which to file petitions*in the Tax Court contesting the proposed …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"50"}},{"t":"case","label":"United States v. Calandra","cite":"414 U.S. 338","y":1974,"id":"1973/72-734","sc":1,"ar":1,"sum":"The Supreme Court held that the exclusionary rule does not apply in grand jury proceedings. The purpose of a grand jury is to determine whether a crime was committed and whether to charge someone in connection with that crime. Using the exclusionary rule would interfere with that purpose. The exclusionary rule is also meant to deter police misconduct, not provide a new constitutional right.","sumSrc":"Oyez","by":{"0":"30","3":"8, 9"}},{"t":"case","label":"United States v. Chemical Foundation, Inc.","cite":"272 U.S. 1","y":1926,"id":"scdb/1926-001","sc":1,"sum":"1. A decree of the Circuit Court of Appeals, entered prior to the taking effect of the Jurisdictional Act of February 13, 1925, and affirming dismissal on the merits of a bill by the United States to set aside, as unauthorized and fraudulently procured, sales of patent and other rights and properties seized pursuant to the Trading, with the Enemy Act, was reviewable by this Court on appeal (Jud. Code §§ 128, 241). …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"41"}},{"t":"case","label":"United States v. DeSantis","cite":"870 F.2d 536","y":1989,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/870/536/","by":{"0":"23"}},{"t":"case","label":"United States v. Mobley","cite":"40 F.3d 688","y":1994,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/40/688/","by":{"0":"23"}},{"t":"case","label":"United States v. Patane","cite":"542 U.S. 630","y":2004,"id":"2003/02-1183","sc":1,"op":2,"ar":2,"sum":"Two other justices also held that the physical evidence was constitutionally admissible, but did so with the understanding that the Miranda warnings must be accommodated to other objectives of the criminal justice system. They did not discuss whether the Miranda warnings were, in themselves, constitutionally required.","sumSrc":"Oyez","by":{"0":"passim","1":"10, 12","2":"14,30-34","3":"1, 5, 7, 10, 21"}},{"t":"case","label":"United States v. Verdugo-Urquidez","cite":"494 U.S. 259","y":1990,"id":"1989/88-1353","sc":1,"sum":"The text of the Fourth Amendment concerns \"the people,\" suggesting a concern with persons who are part of the national community, as contrasted with aliens without any substantial connection to the U.S. Moreover, extraterritorial aliens are not even entitled to rights under the Fifth Amendment, which speaks in the relatively more universal term of \"person.\" And non-\"fundamental\" rights are not even guaranteed to inhabitants of unincorporated territories under U.S sovereign control, much less aliens.","sumSrc":"Oyez","by":{"0":"33","1":"7","2":"38,41","3":"24"}},{"t":"case","label":"Page(s) Withrow v. Williams","cite":"507 U.S. 680","y":1993,"id":"1992/91-1030","sc":1,"op":5,"sum":"The Supreme Court held that the decision in Stone had been one of prudence rather than one of jurisdiction.","sumSrc":"Oyez","by":{"0":"33","1":"11, 22","2":"27,28,51"}},{"t":"case","label":"Yarborough v. Alvarado","cite":"541 U.S. 652","y":2004,"id":"2003/02-1684","sc":1,"sum":"In a 5-to-4 decision written by Justice Anthony Kennedy, the Court ruled that the purpose of the Court's Miranda decision was to provide an objective rule readily understandable by police officers: when interrogating a suspect who is \"in custody,\" an officer must first read the suspect his Miranda rights.","sumSrc":"Oyez","by":{"0":"44"}},{"t":"const","label":"Amendment V","clauses":[["grand-jury","Grand Jury Clause"],["double-jeopardy","Double Jeopardy Clause"],["self-incrimination","Self-Incrimination Clause"],["due-process-5","Due Process Clause (Fifth Amendment)"],["takings","Takings Clause"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"0":"16, 18, 25","1":"24","2":"passim"}},{"t":"usc","label":"18 U.S.C. § 3501","url":"https://www.law.cornell.edu/uscode/text/18/3501","subs":["(a)","(b)"],"stext":{"head":"§3501. Admissibility of confessions","paras":[[0,"(a) In any criminal prosecution brought by the United States or by the District of Columbia, a confession, as defined in subsection (e) hereof, shall be admissible in evidence if it is voluntarily given. Before such confession is received in evidence, the trial judge shall, out of the presence of the jury, determine any issue as to voluntariness. If the trial judge determines that the confession was voluntarily made it shall be admitted in evidence and the trial judge shall permit the jury to hear relevant evidence on the issue of voluntariness and shall instruct the jury to give such weight to the confession as the jury feels it deserves under all the circumstances."],[0,"(b) The trial judge in determining the issue of voluntariness shall take into consideration all the circumstances surrounding the giving of the confession, including (1) the time elapsing between arrest and arraignment of the defendant making the confession, if it was made after arrest and before arraignment, (2) whether such defendant knew the nature of the offense with which he was charged or of which he was suspected at the time of making the confession, (3) whether or not such defendant was advised or knew that he was not required to make any statement and that any such statement could be used against him, (4) whether or not such defendant had been advised prior to questioning of his right to the assistance of counsel; and (5) whether or not such defendant was without the assistance of counsel when questioned and when giving such confession."],[0,"The presence or absence of any of the above-mentioned factors to be taken into consideration by the judge need not be conclusive on the issue of voluntariness of the confession."],[0,"(c) In any criminal prosecution by the United States or by the District of Columbia, a confession made or given by a person who is a defendant therein, while such person was under arrest or other detention in the custody of any law-enforcement officer or law-enforcement agency, shall not be inadmissible solely because of delay in bringing such person before a magistrate judge or other officer empowered to commit persons charged with offenses against the laws of the United States or of the District of Columbia if such confession is found by the trial judge to have been made voluntarily and if the weight to be given the confession is left to the jury and if such confession was made or given by such person within six hours immediately following his arrest or other detention: Provided, That the time limitation contained in this subsection shall not apply in any case in which the delay in bringing such person before such magistrate judge or other officer beyond such six-hour period is found by the trial judge to be reasonable considering the means of transportation and the distance to be traveled to the nearest available such magistrate judge or other officer."],[0,"(d) Nothing contained in this section shall bar the admission in evidence of any confession made or given voluntarily by any person to any other person without interrogation by anyone, or at any time at which the person who made or gave such confession was not under arrest or other detention."],[0,"(e) As used in this section, the term \"confession\" means any confession of guilt of any criminal offense or any self-incriminating statement made or given orally or in writing."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3501?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§3501. Admissibility of confessions","tname":"Crimes and Criminal Procedure","by":{"0":"27, 27"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","stext":{"head":"§1983. Civil action for deprivation of rights","paras":[[0,"Every person who, under color of any statute, ordinance, regulation, custom, or usage, of any State or Territory or the District of Columbia, subjects, or causes to be subjected, any citizen of the United States or other person within the jurisdiction thereof to the deprivation of any rights, privileges, or immunities secured by the Constitution and laws, shall be liable to the party injured in an action at law, suit in equity, or other proper proceeding for redress, except that in any action brought against a judicial officer for an act or omission taken in such officer's judicial capacity, injunctive relief shall not be granted unless a declaratory decree was violated or declaratory relief was unavailable. For the purposes of this section, any Act of Congress applicable exclusively to the District of Columbia shall be considered to be a statute of the District of Columbia."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1983?type=usc&year=mostrecent&link-type=html"},"op":39,"ar":11,"head":"§1983. Civil action for deprivation of rights","tname":"The Public Health and Welfare","by":{"0":"passim","1":"2"}},{"t":"case","label":"Albright v. Oliver","cite":"510 U.S. 266","y":1994,"id":"1993/92-833","sc":1,"sum":"The Court ruled that Section 1983 relief for prosecution without probable cause is only valid if the prosecuted party claims Fourth Amendment (pretrial rights) violations.","sumSrc":"Oyez","by":{"1":"18"}},{"t":"case","label":"Baker v. McCollan","cite":"443 U.S. 137","y":1979,"id":"1978/78-752","sc":1,"sum":"Respondent failed to satisfy § 1983's threshold requirement that the plaintiff be deprived of a right \"secured by the Constitution and laws,\" and hence had no claim cognizable under § 1983.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18"}},{"t":"case","label":"Beckwith v. United States","cite":"425 U.S. 341","y":1976,"id":"1975/74-1243","sc":1,"sum":"Statements made by petitioner taxpayer to Internal Revenue agents during the course of a noncustodial interview in a criminal tax investigation held admissible against him in the ensuing criminal tax fraud prosecution even though he was not given warnings required by Miranda v. Arizona, 384 U. S. 436. Although the \"focus\" of the investigation may have been on petitioner when he was interviewed, in the sense that his …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"13"}},{"t":"case","label":"Berghuis v. Thompkins","cite":"560 U.S. 370","y":2010,"id":"2009/08-1470","sc":1,"sum":"The Court held that a Michigan state court did not deprive a prisoner of his Miranda rights or his right to effective counsel because he failed to state his defense of those rights \"unambiguously.\"","sumSrc":"Oyez","by":{"1":"13"}},{"t":"case","label":"(III) Cases—Continued: Bivens v. Six Unknown Named Agents of Federal Bureau of Narcotics","cite":"403 U.S. 388","y":1971,"id":"1970/301","sc":1,"sum":"The Supreme Court held that Bivens does have a cause of action for damages arising from the federal agents Fourth Amendment violations. Bivens must provide proof of his injuries in order to recover. The Court did not reach the privilege question because the Court of Appeals did not consider the question.","sumSrc":"Oyez","by":{"1":"2"}},{"t":"case","label":"Board of the County Commissioners v. Brown","cite":"520 U.S. 397","y":1997,"id":"1996/95-1100","sc":1,"sum":"Authored by Justice Sandra Day O'Connor, the Court ruled that municipalities are not liable for hiring employees who violate someone's rights unless a reasonable policymaker would conclude that the \"plainly obvious consequence . . . would be the deprivation of a third party's federally protected rights.","sumSrc":"Oyez","by":{"1":"16","2":"47"}},{"t":"case","label":"Bram v. United States","cite":"168 U.S. 532","y":1897,"id":"scdb/1897-041","sc":1,"op":1,"ar":1,"sum":"This was an indictment for murder alleged to have been committed on an American vessel on the high seas. After the crime was discovered, Brown, a sailor, was put in irons and the vessel was headed for Halifax. Before it reached there Brown charged Bram with the commission of the crime, saying that he had seen him do it. Bram was then also put in irons. On the arrival at Halifax, Power, a policeman and detective in …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"7"}},{"t":"case","label":"Briscoe v. LaHue","cite":"460 U.S. 325","y":1983,"id":"1982/81-1404","sc":1,"ar":1,"sum":"Title 42 U. S. C. § 1983 (1976 ed., Supp. V) does not authorize a convicted state defendant to assert a claim for damages against a police officer for giving perjured testimony at the defendant's criminal trial.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"26","2":"48","3":"19"}},{"t":"case","label":"Brown v. Mississippi","cite":"297 U.S. 278","y":1936,"id":"scdb/1935-089","sc":1,"sum":"Convictions of murder, which rest solely upon confessions shown to have beenextorted by officers of the State by torture of the accused, are void under the due process clause of the Fourteenth Amendment. Pp. 279, 285. \" - 173 Miss; 542; 158 So. 339; 161 So. 465, reversed. BROWN v. MISSISSIPPI.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"8"}},{"t":"case","label":"Butz v. Economou","cite":"438 U.S. 478","y":1978,"id":"1977/76-709","sc":1,"sum":"Federal officials who perform adjudicatory, or other similar prosecutorial functions, cannot, however, be held liable for mere \"good faith\" judgment errors. The Court reasoned that the risk of making unconstitutional determinations is outweighed by the need to preserve independent judgement, through grants of absolute immunity to judges and other similarly situated decision makers.","sumSrc":"Oyez","by":{"1":"27"}},{"t":"case","label":"City of Rancho Palos Verdes v. Abrams","cite":"544 U.S. 113","y":2005,"id":"2004/03-1601","sc":1,"op":1,"sum":"The Court held that Abrams could not enforce the limitations of the Telecommunications Act on local authorities through federal liability law, because the act provides its own judicial remedy. Congress could not have meant the judicial remedy expressly authorized by the Telecommunications Act to co-exist with an alternative remedy.","sumSrc":"Oyez","by":{"1":"21"}},{"t":"case","label":"County of Sacramento v. Lewis","cite":"523 U.S. 833","y":1998,"id":"1997/96-1337","sc":1,"sum":"In a unanimous decision the Court first ruled that the Fourth Amendment's reasonableness standards prevented its illegal seizure protections from applying to high-speed police chases. Such incidents are merely pursuits and do not constitute actual seizures, especially if they fail due to the death of the subject.","sumSrc":"Oyez","by":{"1":"14"}},{"t":"case","label":"Crawford v. Washington","cite":"541 U.S. 36","y":2004,"id":"2003/02-9410","sc":1,"sum":"The Court sided with Crawford and ruled that the Sixth Amendment's Confrontation Clause gives defendants the right to confront witnesses and cross-examine their testimony. This includes testimony police gather. The Court reasoned that the Framers intended the Confrontation Clause to prohibit out-of-court testimony as evidence against defendants.","sumSrc":"Oyez","by":{"1":"7"}},{"t":"case","label":"Duckworth v. Eagan","cite":"492 U.S. 195","y":1989,"id":"1988/88-317","sc":1,"op":1,"sum":"In a closely divided decision, the Court held that informing Eagan that an attorney would be appointed for him \"if and when you go to court\" did not render the Miranda warnings inadequate. The Court reasoned that officers did not have to use the specific language of the Miranda decision so long as they reasonably conveyed to suspects their constitutional rights.","sumSrc":"Oyez","by":{"1":"13","2":"27"}},{"t":"case","label":"Graham v. Connor","cite":"490 U.S. 386","y":1989,"id":"1988/87-6571","sc":1,"sum":"In a unanimous ruling written by Justice William Rehnquist, the Court held that claims of excessive force used by government officials are properly analyzed under the Fourth Amendment’s “objective reasonableness” standard. The Court vacated the directed verdict and remanded the case to the district court to be decided by that standard.","sumSrc":"Oyez","by":{"1":"14","3":"21"}},{"t":"case","label":"Hartman v. Moore","cite":"547 U.S. 250","y":2006,"id":"2005/04-1495","sc":1,"ar":1,"sum":"The Court ruled in favor of the postal inspectors, overruling the Court of Appeals. The opinion by Justice David Souter held that plaintiffs alleging retaliatory prosecution must prove that the law enforcement agents lacked probable cause. Probable cause, the Court ruled, is a crucial component of the \"chain of causation\" needed to evaluate retaliatory prosecution charges.","sumSrc":"Oyez","by":{"1":"26","2":"40","3":"23"}},{"t":"case","label":"Heck v. Humphrey","cite":"512 U.S. 477","y":1994,"id":"1993/93-6188","sc":1,"op":1,"ar":1,"sum":"The Supreme Court held that a defendant cannot claim damages for an allegedly unconstitutional conviction or imprisonment without showing that the conviction or sentence has been overturned in some way. The defendant must also exhaust state court remedies before bringing a §1983 action.","sumSrc":"Oyez","by":{"1":"21, 23","2":"50,51"}},{"t":"case","label":"Hemi Group, LLC v. City of New York","cite":"559 U.S. 1","y":2010,"id":"2009/08-969","sc":1,"op":2,"sum":"The Court held that the city of New York had standing to sue out-of-state cigarette vendors under the Racketeer Influenced and Corrupt Organizations Act.","sumSrc":"Oyez","by":{"1":"19"}},{"t":"case","label":"Imbler v. Pachtman","cite":"424 U.S. 409","y":1976,"id":"1975/74-5435","sc":1,"sum":"The Court held that prosecutors have the same absolute immunity under Section 1983 that they had under common law in malicious prosecution suits.","sumSrc":"Oyez","by":{"1":"18"}},{"t":"case","label":"Jackson v. Denno","cite":"378 U.S. 368","y":1964,"id":"1963/62","sc":1,"sum":"The Court held that the New York procedure did not allow for a reliable determination of whether or not the confessions were voluntary. Because the judge does not rule on the issue and the jury only reports on the ultimate question of guilt or innocence, there is no way to determine whether the jury found he confession voluntary.","sumSrc":"Oyez","by":{"1":"8","3":"22"}},{"t":"case","label":"Johnson v. New Jersey","cite":"384 U.S. 719","y":1966,"id":"1965/762","sc":1,"op":10,"sum":"Petitioners' confessions were offered in evidence by the State in their trial for felony murder, at which they were found guilty and sentenced to death. Their convictions became final six years ago. On collateral attack petitioners now argue that the confessions were inadmissible under Eacobedo v. Illinois, 378 U. S. 478. The New Jersey Supreme Court held that Escobedo did not apply -retroactively.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"9"}},{"t":"case","label":"Kastigar v. United States","cite":"406 U.S. 441","y":1972,"id":"1971/70-117","sc":1,"sum":"The Court found that compelled testimony is legitimate given the grant of immunity. Justice Powell found that the protections of immunity that a congressional statute provided were \"coextensive with the scope of the privilege against self-incrimination\" and \"sufficient to compel testimony over a claim of the privilege.\".","sumSrc":"Oyez","by":{"1":"25"}},{"t":"case","label":"Lynumn v. Illinois","cite":"372 U.S. 528","y":1963,"id":"1962/9","sc":1,"sum":"Petitioner's confession was coerced; its admission in evidence violated the Due Process Clause of the Fourteenth Amendment; and the judgment affirming her conviction is reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"7, 25"}},{"t":"case","label":"Lyons v. Oklahoma","cite":"322 U.S. 596","y":1944,"id":"scdb/1943-116","sc":1,"sum":"1. The instruction to the jury in this case fairly raised the question whether the challenged confession was voluntary, and did not deny to the defendant any right under the Fourteenth Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24"}},{"t":"case","label":"Malinski v. New York","cite":"324 U.S. 401","y":1945,"id":"scdb/1944-045","sc":1,"sum":"1. Upon review of a state court judgment affirming convictions of codefendants Malinski and Rudish on a charge of murder, denial of rights under the due process clause of the Fourteenth Amendment being claimed, the judgment against Malinski is reversed and that against Rudish is affirmed. Pp. 402, 412.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"8"}},{"t":"case","label":"Malloy v. Hogan","cite":"378 U.S. 1","y":1964,"id":"1963/110","sc":1,"op":1,"sum":"In a 5-to-4 opinion, the Court held that the Fifth Amendment's exception from compulsory self-incrimination is protected by the Fourteenth Amendment against abridgement by a state. When determining if state officers properly obtained a confession, one must focus on whether the statements were made freely and voluntarily without any direct or implied promised or improper influence.","sumSrc":"Oyez","by":{"1":"7","2":"20"}},{"t":"case","label":"Manuel v. City of Joliet","cite":"137 S. Ct. 911","y":2017,"id":"2016/14-9496","sc":1,"sum":"The Court held that an individual’s right to be free from unreasonable search and seizure continues throughout the legal process of a criminal case.","sumSrc":"Oyez","by":{"1":"19, 20","3":"20"}},{"t":"case","label":"Middlesex County Sewerage Authority v. National Sea Clammers Ass’n","cite":"453 U.S. 1","y":1981,"id":"1980/79-1711","sc":1,"sum":"Respondents (an organization whose members harvest fish and shellfish off the coast of New York and New Jersey and one individual member) brought suit in Federal District Court against petitioners (various governmental entities and officials from New York, New Jersey, and the Federal Government), alleging damage to fishing grounds caused by discharges and ocean dumping of sewage and other waste. Invoking a number of …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"21"}},{"t":"case","label":"Monell v. Department of Social Services","cite":"436 U.S. 658","y":1978,"id":"1977/75-1914","sc":1,"sum":"The Court held that the legislative history of the Civil Rights Act of 1871, and specifically the Sherman Amendment, indicated that municipalities could be liable for the infringement of constitutional rights. Additionally, by 1871 there was a clear legislative and precedent-based history for municipal corporations — such as a school board — to be considered a “person” for the purpose of lawsuits and liability.","sumSrc":"Oyez","by":{"1":"17","2":"45,47,54"}},{"t":"case","label":"Montana v. United States","cite":"440 U.S. 147","y":1979,"id":"1978/77-1134","sc":1,"sum":"The United States is collaterally estopped from challenging the prior judgment of the Montana Supreme Court.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"22"}},{"t":"case","label":"Moran v. Burbine","cite":"475 U.S. 412","y":1986,"id":"1985/84-1485","sc":1,"sum":"The Court held that failure to inform Burbine about the attorney’s phone call did not affect the validity of his waiver of rights.","sumSrc":"Oyez","by":{"1":"20","2":"32"}},{"t":"case","label":"New Jersey v. Portash","cite":"440 U.S. 450","y":1979,"id":"1978/77-1489","sc":1,"sum":"Under the Fifth Amendment privilege against compulsory self-incrimination made binding on the States by the Fourteenth Amendment, respondent's testimony before the grand jury under a grant of immunity could not constitutionally be used against him in the later criminal trial.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"25"}},{"t":"case","label":"Palsgraf v. Long Island R. Co.","cite":"162 N.E. 99","y":1928,"court":"N.Y.","url":"https://www.courtlistener.com/c/N.E./162/99/","by":{"1":"19"}},{"t":"case","label":"Parke v. Raley","cite":"506 U.S. 20","y":1992,"id":"1992/91-719","sc":1,"sum":"In 1986, respondent Raley was charged with robbery and with being a persistent felony offender under a Kentucky statute that enhances sentences for repeat felons. He moved to suppress the 1979 and 1981 guilty pleas that formed the basis for the latter charge, claiming that they were invalid because the records contained no transcripts of the proceedings and hence did not affirmatively show, as required by Boykin v. …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"17"}},{"t":"case","label":"Parklane Hosiery Co. v. Shore","cite":"439 U.S. 322","y":1979,"id":"1978/77-1305","sc":1,"op":1,"sum":"Respondent brought this stockholder's class action in the District Court for damages and other relief against petitioners, a corporation, its officers, directors, and stockholders, who allegedly had issued a materially false and misleading proxy statement in violation of the federal securities laws and Securities and Exchange Commission (SEC) regulations. Before the action came to trial the SEC sued the same …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"22"}},{"t":"case","label":"Pennsylvania v. Muniz","cite":"496 U.S. 582","y":1990,"id":"1989/89-213","sc":1,"sum":"The Court held that the Fifth Amendment distinguishes between real or physical evidence and testimonial evidence, of which only testimonial evidence is protected under the Amendment.","sumSrc":"Oyez","by":{"1":"13"}},{"t":"case","label":"Pierson v. Ray","cite":"386 U.S. 547","y":1967,"id":"1966/79","sc":1,"sum":"Petitioners,t,'members of a group of white and Negro clergymen on a \"prayer pilgrimage\" to promote racial integration, attempted to use a segregated interstate bus terminal waiting room in Jackson, Mississippi, in 1961. They were arrested by respondent policemen and charged with conduct breaching the peace in violation of § 2087.5 of the Mississippi Code which this Court, in 1965, held unconstitutional in Thomas v. …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18"}},{"t":"case","label":"Preiser v. Rodriguez","cite":"411 U.S. 475","y":1973,"id":"1972/71-1369","sc":1,"op":1,"sum":"When a state prisoner challenges the fact or duration of his physical imprisonment and by way of relief seeks a determination that he is entitled to immediate release or a speedier release, his sole federal remedy is a writ of habeas corpus.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"21, 23","2":"50"}},{"t":"case","label":"Rehberg v. Paulk","cite":"566 U.S. 356","y":2012,"id":"2011/10-788","sc":1,"sum":"The Court held that a witness in a grand jury proceeding is entitled to the same absolute immunity from a §1983 action as a witness who testifies at trial.","sumSrc":"Oyez","by":{"1":"18","2":"48-49"}},{"t":"case","label":"Rhode Island v. Innis","cite":"446 U.S. 291","y":1980,"id":"1979/78-1076","sc":1,"sum":"In a 6-to-3 decision, the Court held that the Miranda safeguards came into play \"whenever a person in custody is subjected to either express questioning or its functional equivalent,\" noting that the term \"interrogation\" under Miranda included \"any words or actions on the part of the police (other than those normally attendant to arrest and custody) that the police should know are reasonably likely to elicit an incriminating response from the subject.\" The Court then found that the officers' conversation did not qualify as words or actions that they should have known were reasonably likely to elicit such a response from Innis.","sumSrc":"Oyez","by":{"1":"13"}},{"t":"case","label":"Robertson v. Sichel","cite":"127 U.S. 507","y":1888,"id":"scdb/1887-270","sc":1,"sum":"A collector of customs is not personally liable for a tort committed by his subordinates, in negligently keeping the trunk of an arriving passenger on a pier, instead of sending it to the public store, so that it was destroyed by fire: whore there is no evidence to connect the collector personally with the wrong, or that the subordinates were not competjnt, or were not properly selected for their positions.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"17"}},{"t":"case","label":"United States v. Abdulmutallab","cite":"739 F.3d 891","y":2014,"url":"https://www.courtlistener.com/c/F.3d/739/891/","by":{"1":"12"}},{"t":"case","label":"United States v. Khweis","cite":"971 F.3d 453","y":2020,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/971/453/","by":{"1":"12"}},{"t":"case","label":"United States v. Tsarnaev","cite":"968 F.3d 24","y":2020,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/968/24/","by":{"1":"12"}},{"t":"case","label":"Wong Sun v. United States","cite":"371 U.S. 471","y":1963,"id":"1962/36","sc":1,"op":2,"sum":"The Supreme Court held that the police did not have probable cause to justify the arrests. With regard to Toy, the court should exclude all evidence found during the search because they are the “fruits” of an unlawful search. The unsigned statement was not corroborated, so it gave no basis for conviction. Sun’s unsigned confession and evidence against him were admissible.","sumSrc":"Oyez","by":{"1":"10"}},{"t":"const","label":"Amendment IV","clauses":[["fourth-amendment","Fourth Amendment"]],"text":"The right of the people to be secure in their persons, houses, papers, and effects, against unreasonable searches and seizures, shall not be violated, and no Warrants shall issue, but upon probable cause, supported by Oath or affirmation, and particularly describing the place to be searched, and the persons or things to be seized.","by":{"1":"7, 11, 14","2":"33-34"}},{"t":"const","label":"Amendment XIV","clauses":[["due-process-14","Due Process Clause (Fourteenth Amendment)"]],"by":{"1":"8","2":"passim, 28"}},{"t":"usc","label":"18 U.S.C. § 242","url":"https://www.law.cornell.edu/uscode/text/18/242","by":{"1":"1, 14"}},{"t":"usc","label":"28 U.S.C. § 2254","url":"https://www.law.cornell.edu/uscode/text/28/2254","subs":["(a)"],"stext":{"head":"§2254. State custody; remedies in Federal courts","paras":[[0,"(a) The Supreme Court, a Justice thereof, a circuit judge, or a district court shall entertain an application for a writ of habeas corpus in behalf of a person in custody pursuant to the judgment of a State court only on the ground that he is in custody in violation of the Constitution or laws or treaties of the United States."],[0,"(b)(1) An application for a writ of habeas corpus on behalf of a person in custody pursuant to the judgment of a State court shall not be granted unless it appears that—"],[1,"(A) the applicant has exhausted the remedies available in the courts of the State; or"],[1,"(B)(i) there is an absence of available State corrective process; or"],[1,"(ii) circumstances exist that render such process ineffective to protect the rights of the applicant."],[0,"(2) An application for a writ of habeas corpus may be denied on the merits, notwithstanding the failure of the applicant to exhaust the remedies available in the courts of the State."],[0,"(3) A State shall not be deemed to have waived the exhaustion requirement or be estopped from reliance upon the requirement unless the State, through counsel, expressly waives the requirement."],[0,"(c) An applicant shall not be deemed to have exhausted the remedies available in the courts of the State, within the meaning of this section, if he has the right under the law of the State to raise, by any available procedure, the question presented."],[0,"(d) An application for a writ of habeas corpus on behalf of a person in custody pursuant to the judgment of a State court shall not be granted with respect to any claim that was adjudicated on the merits in State court proceedings unless the adjudication of the claim—"],[1,"(1) resulted in a decision that was contrary to, or involved an unreasonable application of, clearly established Federal law, as determined by the Supreme Court of the United States; or"],[1,"(2) resulted in a decision that was based on an unreasonable determination of the facts in light of the evidence presented in the State court proceeding."],[0,"(e)(1) In a proceeding instituted by an application for a writ of habeas corpus by a person in custody pursuant to the judgment of a State court, a determination of a factual issue made by a State court shall be presumed to be correct. The applicant shall have the burden of rebutting the presumption of correctness by clear and convincing evidence."],[0,"(2) If the applicant has failed to develop the factual basis of a claim in State court proceedings, the court shall not hold an evidentiary hearing on the claim unless the applicant shows that—"],[1,"(A) the claim relies on—"],[2,"(i) a new rule of constitutional law, made retroactive to cases on collateral review by the Supreme Court, that was previously unavailable; or"],[2,"(ii) a factual predicate that could not have been previously discovered through the exercise of due diligence; and"],[1,"(B) the facts underlying the claim would be sufficient to establish by clear and convincing evidence that but for constitutional error, no reasonable factfinder would have found the applicant guilty of the underlying offense."],[0,"(f) If the applicant challenges the sufficiency of the evidence adduced in such State court proceeding to support the State court's determination of a factual issue made therein, the applicant, if able, shall produce that part of the record pertinent to a determination of the sufficiency of the evidence to support such determination. If the applicant, because of indigency or other reason is unable to produce such part of the record, then the State shall produce such part of the record and the Federal court shall direct the State to do so by order directed to an appropriate State official. If the State cannot provide such pertinent part of the record, then the court shall determine under the existing facts and circumstances what weight shall be given to the State court's factual determination."],[0,"(g) A copy of the official records of the State court, duly certified by the clerk of such court to be a true and correct copy of a finding, judicial opinion, or other reliable written indicia showing such a factual determination by the State court shall be admissible in the Federal court proceeding."],[0,"(h) Except as provided in section 408 of the Controlled Substances Act, in all proceedings brought under this section, and any subsequent proceedings on review, the court may appoint counsel for an applicant who is or becomes financially unable to afford counsel, except as provided by a rule promulgated by the Supreme Court pursuant to statutory authority. Appointment of counsel under this section shall be governed by section 3006A of title 18."],[0,"(i) The ineffectiveness or incompetence of counsel during Federal or State collateral post-conviction proceedings shall not be a ground for relief in a proceeding arising under section 2254."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2254?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2254. State custody; remedies in Federal courts","tname":"Judiciary and Judicial Procedure","by":{"1":"23","3":"8"}},{"t":"usc","label":"28 U.S.C. § 2255","url":"https://www.law.cornell.edu/uscode/text/28/2255","by":{"1":"23"}},{"t":"case","label":"Alexander v. Sandoval","cite":"532 U.S. 275","y":2001,"id":"2000/99-1908","sc":1,"sum":"The Court held that there is no private right of action to enforce disparate-impact regulations promulgated under Title VI. \"Title VI itself directly reaches only instances of intentional discrimination,\" wrote Justice Scalia, \"[n]either as originally enacted nor as later amended does Title VI display an intent to create a freestanding private right of action to enforce regulations promulgated under [section 602].\" Justice John Paul Stevens filed a dissenting opinion, which was join by Justices David H. Souter, Ruth Bader Ginsburg, and Stephen G. Breyer.","sumSrc":"Oyez","by":{"2":"50"}},{"t":"case","label":"Arizona v. Roberson","cite":"486 U.S. 675","y":1988,"id":"1987/87-354","sc":1,"op":3,"sum":"The Court held that once a suspect has requested counsel, police cannot interrogate him unless he initiates the contact.","sumSrc":"Oyez","by":{"2":"26"}},{"t":"case","label":"Bank of Am. Corp. v. City of Miami","cite":"137 S. Ct. 1296","y":2017,"id":"2016/15-1111","sc":1,"sum":"The Court determined that the “aggrieved persons” language of the Fair Housing Act (FHA) does not impose a more narrow standing standard than Article III does and allows a city to sue, but the proximate cause standard requires the plaintiffs to show more than the possibility that a defendant could have foreseen the harm.","sumSrc":"Oyez","by":{"2":"38,46"}},{"t":"case","label":"Buckley v. Fitzsimmons","cite":"509 U.S. 259","y":1993,"id":"1992/91-7849","sc":1,"sum":"Petitioner Buckley sought damages, under 42 U. S. C. § 1983, from respondent prosecutors for fabricating evidence during the preliminary investigation of a highly publicized rape and murder in Illinois and making false statements at a press conference announcing the return of an indictment against him. He claimed that when three separate lab studies failed to make a reliable connection between a bootprint at the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"49"}},{"t":"case","label":"Burrell v. Virginia","cite":"395 F.3d 508","y":2005,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/395/508/","by":{"2":"14"}},{"t":"case","label":"Caldwell v. City & Cty. of S.F","cite":"899 F.3d 1105","y":2018,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/899/1105/","by":{"2":"42"}},{"t":"case","label":"City of Monterey v. Del Monte Dunes","cite":"526 U.S. 687","y":1999,"id":"1998/97-1235","sc":1,"sum":"The Court held, in an opinion authored by Justice Anthony M. Kennedy, that property owners who file a Section 1983 civil rights suit seeking compensation for an alleged taking of their property can have a jury trial in some circumstances. \"[T]he disputed questions were whether the government had denied a constitutional right outside the bounds of its authority, and, if so, the extent of any resulting damages.\" Justice Kennedy then added: \"These were questions for the jury.\".","sumSrc":"Oyez","by":{"2":"36"}},{"t":"case","label":"Cty. Of Riverside v. McLaughlin","cite":"500 U.S. 44","y":1991,"id":"1990/89-1817","sc":1,"op":1,"sum":"The Court held that Riverside's actions did not comply with the Gerstein precedent. Justice O'Connor argued that it was the state's burden to demonstrate extraordinary circumstances when delaying probable cause determinations beyond 48 hours. The lower court in this case had placed that responsibility on the accused. Intervening weekends or complicated pretrial proceedings were not legitimate reasons for delay.","sumSrc":"Oyez","by":{"2":"10"}},{"t":"case","label":"Corley v. United States","cite":"556 U.S. 303","y":2009,"id":"2008/07-10441","sc":1,"sum":"The Court found that voluntary confessions made more than six hours after arrest before the person has been presented before judicial officers are inadmissible.","sumSrc":"Oyez","by":{"2":"52"}},{"t":"case","label":"Dennis v. Higgins","cite":"498 U.S. 439","y":1991,"id":"1990/89-1555","sc":1,"op":2,"ar":1,"sum":"Suits for violations of the Commerce Clause may be brought under § 1983.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"54"}},{"t":"case","label":"-viii- Cases Doyle v. Ohio","cite":"426 U.S. 610","y":1976,"id":"1975/75-5014","sc":1,"op":2,"sum":"The use for impeachment purposes of petitioners' silence, at the time of arrest and after they received Miranda warnings, violated the Due Process Clause of the Fourteenth Amendment. Post-arrest silence following such warnings is insolubly ambiguous; moreover, it would be fundamentally unfair to allow an arrestee's silence to be used to impeach an explanation subsequently given at trial after he had been impliedly …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"26"}},{"t":"case","label":"Edwards v. Arizona","cite":"451 U.S. 477","y":1981,"id":"1980/79-5269","sc":1,"sum":"The use of petitioner's confession against him at his trial violated his right under the Fifth and Fourteenth Amendments to have counsel present during custodial interrogation, as declared in Miranda, supra. Having exercised his right on January 19 to have counsel present during interrogation, petitioner did not validly waive that right on the 20th.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"27,32"}},{"t":"case","label":"Exxon Co., U.S.A. v. Sofec, Inc.","cite":"517 U.S. 830","y":1996,"id":"1995/95-129","sc":1,"sum":"The Court held that a plaintiff in admiralty that is the superseding cause of its own injury, and thus the sole, proximate cause, cannot recover part of its damages from tort-feasors or contracting partners whose blameworthy actions were causes in fact of the injury.","sumSrc":"Oyez","by":{"2":"37-38"}},{"t":"case","label":"Felder v. Casey","cite":"487 U.S. 131","y":1988,"id":"1987/87-526","sc":1,"sum":"Because the Wisconsin notice-of-claim statute conflicts in both its purpose and effects with § 1983's remedial objectives, and because its enforcement in state-court actions will frequently and predictably produce different outcomes in § 1983 litigation based solely on whether the claim is asserted in state or federal court, it is pre-empted pursuant to the Supremacy Clause when the § 1983 action is brought in a …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"19"}},{"t":"case","label":"Franks v. Delaware","cite":"438 U.S. 154","y":1978,"id":"1977/77-5176","sc":1,"sum":"Where the defendant makes a substantial preliminary showing that a false statement knowingly and intentionally, or with reckless disregard for the truth, was included by the affiant in the warrant affidavit, and if the allegedly false statement is necessary to the finding of probable cause, the Fourth Amendment, as incorporated in the Fourteenth Amendment, requires that a hearing be held at the defendant's request. …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"42"}},{"t":"case","label":"Hannon v. Sanner","cite":"441 F.3d 635","y":2006,"court":"8thCir.","url":"https://www.courtlistener.com/c/F.3d/441/635/","by":{"2":"14"}},{"t":"case","label":"Hudson v. Michigan","cite":"547 U.S. 586","y":2006,"id":"2005/04-1360","sc":1,"ar":1,"sum":"The Court ruled that the general rule excluding evidence obtained in violation of the Fourth Amendment does not apply to the \"knock-and-announce\" rule.","sumSrc":"Oyez","by":{"2":"55"}},{"t":"case","label":"Illinois v. Perkins","cite":"496 U.S. 292","y":1990,"id":"1989/88-1972","sc":1,"sum":"The Court held that conversations between suspects and undercover officers are not afforded Miranda protection since they are not done in a \"police-dominated atmosphere\" where compulsion to confess is present. \"It is the premise of Miranda that the danger of coercion results from the interaction of custody and official interrogation,\" argued Justice Kennedy. There was no danger of coercion in this case.","sumSrc":"Oyez","by":{"2":"32"}},{"t":"case","label":"Jones v. Chicago","cite":"856 F.2d 985","y":1988,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/856/985/","by":{"2":"42"}},{"t":"case","label":"Kalina v. Fletcher","cite":"522 U.S. 118","y":1997,"id":"1997/96-792","sc":1,"sum":"The Court held that section 1983 may create a damages remedy against a prosecutor for making false statements of fact in an affidavit supporting an application for an arrest warrant, since such conduct is not protected by the doctrine of absolute prosecutorial immunity.","sumSrc":"Oyez","by":{"2":"48-49"}},{"t":"case","label":"Lombardi v. City of El Cajon","cite":"117 F.3d 1117","y":1997,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/117/1117/","by":{"2":"36"}},{"t":"case","label":"Malley v. Briggs","cite":"475 U.S. 335","y":1986,"id":"1985/84-1586","sc":1,"sum":"The Court held that a police officer was not entitled to immunity when he caused an unlawful arrest by presenting a judge with an application for a warrant that did not present a probable cause.","sumSrc":"Oyez","by":{"2":"42,45,49","3":"22, 23"}},{"t":"case","label":"Massiah v. United States","cite":"377 U.S. 201","y":1964,"id":"1963/199","sc":1,"sum":"The Supreme Court held that incriminating statements deliberately elicited by federal agents in the absence of counsel after the proceeding has begun violate the Sixth Amendment. The prosecution could not use these statements as evidence against Massiah. Justice Byron R. White dissented, arguing that the statements should be admitted because they were voluntarily made and not coerced.","sumSrc":"Oyez","by":{"2":"38","3":"23"}},{"t":"case","label":"McKinley v. City of Mansfield","cite":"404 F.3d 1006","y":2006,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/404/1006/","by":{"2":"41,42"}},{"t":"case","label":"Milwaukee & Saint Paul Ry. Co. v. Kellogg","cite":"94 U.S. 469","y":1876,"id":"scdb/1876-197","sc":1,"op":1,"sum":"Holding that introduction of an un-Mirandized statement in a criminal trial is “a flat violation of the Self-Incrimination Clause of the Fifth Amendment as construed in Miranda.”.","sumSrc":"brief:2","by":{"2":"37"}},{"t":"case","label":"Monroe v. Pape","cite":"365 U.S. 167","y":1961,"id":"1960/39","sc":1,"ar":1,"sum":"Yes and No. Justice William O. Douglas, writing for the majority, stated that the city police officers, in conducting an unreasonable search and seizure, had committed an action which was under the color of law, and that the police could be held liable individually under the Civil Rights Act. However, the majority further held that a municipality could not be liable under the Civil Rights Act.","sumSrc":"Oyez","by":{"2":"36,37"}},{"t":"case","label":"Mu’Min v. Virginia","cite":"500 U.S. 415","y":1991,"id":"1990/90-5193","sc":1,"sum":"The trial judge's refusal to question prospective jurors about the specific contents of the news reports to which they had been exposed did not violate Mu'Min's Sixth Amendment right to an impartial jury or his right to due process under the Fourteenth Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"5"}},{"t":"case","label":"-xi- Cases Murray v. Earle","cite":"405 F.3d 278","y":2005,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/405/278/","by":{"2":"14,41,42"}},{"t":"case","label":"Orozco v. Texas","cite":"394 U.S. 324","y":1969,"id":"1968/641","sc":1,"op":2,"sum":"Use of admissions at petitioner's trial for murder which were obtained by officers who, while he was in their custody in his bedroom at the boardinghouse where he lived, questioned him about incriminating facts without first informing him of his rights to remain silent, to have a lawyer's advice before making a statement, and to have a lawyer appointed to assist him if he could not afford to hire one, held to have …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"21,29,32","3":"5"}},{"t":"case","label":"Owen v. Independence","cite":"445 U.S. 622","y":1980,"id":"1979/78-1779","sc":1,"sum":"A municipality has no immunity from liability under § 1983 flowing from its constitutional violations and may not assert the good faith of its officers as a defense to such liability.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"18,55"}},{"t":"case","label":"Renda v. King","cite":"347 F.3d 550","y":2003,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/347/550/","by":{"2":"14"}},{"t":"case","label":"Smith v. Phillips","cite":"455 U.S. 209","y":1982,"id":"1981/80-1082","sc":1,"sum":"Respondent was not denied due process of law either by the juror's conduct or by the prosecutors' failure to disclose the juror's job application.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"27"}},{"t":"case","label":"-xii- Cases Smith v. Wade","cite":"461 U.S. 30","y":1983,"id":"1982/81-1196","sc":1,"sum":"Respondent, while an inmate in a Missouri reformatory for youthful first offenders, was harassed, beaten, and sexually assaulted by his cellmates. He brought suit under 42 U. S. C. § 1983 in Federal District Court against petitioner, a guard at the reformatory, and others, alleging that his Eighth Amendment rights had been violated. Because of petitioner's qualified immunity, as a prison guard, from § 1983 …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"37"}},{"t":"case","label":"Sornberger v. City of Knoxville","cite":"434 F.3d 1006","y":2006,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/434/1006/","ar":1,"by":{"2":"14,41,51"}},{"t":"case","label":"Staub v. Proctor Hosp.","cite":"562 U.S. 411","y":2011,"id":"2010/09-400","sc":1,"sum":"The Court held that an employer may be found liable for the discriminatory acts of supervisors, who do not themselves make employment decisions but do influence the employment decision-makers.","sumSrc":"Oyez","by":{"2":"43"}},{"t":"case","label":"Story Parchment Co. v. Paterson Parchment Paper Co.","cite":"282 U.S. 555","y":1931,"id":"scdb/1930-096","sc":1,"sum":"1. On review by certiorari, respondents, without necessity of a crosspetition, may invoke as an additional ground for sustaining the judgment of the lower court a ground which that court had found against them.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"37"}},{"t":"case","label":"Tekoh v. Cty. of Los Angeles","cite":"270 F. Supp. 3d 1163","y":2017,"court":"C.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/270/1163/","by":{"2":"12"}},{"t":"case","label":"Thompson v. Keohane","cite":"516 U.S. 99","y":1995,"id":"1995/94-6615","sc":1,"op":1,"sum":"State-court \"in custody\" rulings, made to determine whether Mirandawarnings are due, do not qualify for a presumption of correctness under §2254(d). Such rulings do not resolve \"a factual issue.\" Instead, they resolve mixed questions of law and fact and therefore warrant independent review by the federal habeas court.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"28"}},{"t":"case","label":"United States v. Leon","cite":"468 U.S. 897","y":1984,"id":"1983/82-1771","sc":1,"sum":"The Court ruled that there is an exception to the exclusionary rule for evidence gathered in \"good faith.\"","sumSrc":"Oyez","by":{"2":"42"}},{"t":"case","label":"United States v. Price","cite":"383 U.S. 787","y":1966,"id":"1965/59","sc":1,"sum":"The Court held that Price and the other defendants violate federal law when they murdered three men on June 21, 1964.","sumSrc":"Oyez","by":{"2":"19"}},{"t":"case","label":"United States v. Washington","cite":"431 U.S. 181","y":1977,"id":"1976/74-1106","sc":1,"sum":"Respondent's grand jury testimony may properly be used against him mna subsequent trial. The comprehensive warnings he received, whether or not such warnings were constitutionally required, dissipated any element of compulsion to self-incrimination that might otherwise have been present. The fact that a subpoenaed grand jury witness is a putative or potential defendant neither impairs nor enlarges his constitutional …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"21"}},{"t":"case","label":"Walker v. Johnston","cite":"312 U.S. 275","y":1941,"id":"scdb/1940-163","sc":1,"sum":"1. Under the statute governing habeas corpus, the writ may be denied if, upon the face of the petition, it appears that the petitioner is not entitled to it.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"43"}},{"t":"case","label":"Weatherford v. Bursey","cite":"429 U.S. 545","y":1977,"id":"1976/75-1510","sc":1,"sum":"Respondent and petitioner Weatherford (hereinafter petitioner), an undercover agent, were arrested for a state criminal offense, each thereafter retaining separate counsel. Petitioner had two pretrial meetings with respondent and respondent's counsel, who had sought petitioner's presence for the purpose of securing information or suggestions as to respondent's defense. Petitioner had no discussions concerning …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"38","3":"23"}},{"t":"const","label":"Amendment VI","clauses":[["sixth-trial","Speedy and Public Trial by Jury"],["confrontation","Confrontation Clause"],["counsel","Right to Counsel"]],"text":"In all criminal prosecutions, the accused shall enjoy the right to a speedy and public trial, by an impartial jury of the State and district wherein the crime shall have been committed, which district shall have been previously ascertained by law, and to be informed of the nature and cause of the accusation; to be confronted with the witnesses against him; to have compulsory process for obtaining witnesses in his favor, and to have the Assistance of Counsel for his defence.","by":{"2":"38"}},{"t":"case","label":"-xiv- Other Authorities Brief for Amicus Curiae the United States of America, Dickerson v. United States","cite":"530 U.S. 420","y":2000,"url":"https://supreme.justia.com/cases/federal/us/530/420/","sc":1,"op":17,"sum":"Explaining that the Court “do[es] not hold a supervisory power over the courts of the several States”.","sumSrc":"opinion","by":{"2":"23"}},{"t":"case","label":"City of Springfield v. Kibbe","cite":"480 U.S. 257","y":1987,"id":"1986/85-1217","sc":1,"sum":"The writ of certiorari is dismissed as improvidently granted. Although petitioner argues here that a heightened negligence standard does not suffice under Monell's requirement of a municipal policy, this Court ordinarily will not decide questions not raised or litigated in the lower courts, especially where the party seeking to argue the issue has failed to object to a jury instruction, as required by Rule 51 of the …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"1"}},{"t":"case","label":"Devereaux v. Abbey","cite":"263 F.3d 1070","y":2001,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/263/1070/","by":{"3":"21"}},{"t":"case","label":"Nieves v. Bartlett","cite":"139 S. Ct. 1715","y":2019,"id":"2018/17-1174","sc":1,"ar":1,"sum":"Because police officers had probable cause to arrest Bartlett, his First Amendment retaliatory arrest claim fails as a matter of law.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"23"}},{"t":"case","label":"US Airways, Inc. v. McCutchen","cite":"569 U.S. 88","y":2013,"id":"2012/11-1285","sc":1,"sum":"The Court held that when a contract is silent on allocation of relief, the parties' intentions are best determined by the common-fund doctrine.","sumSrc":"Oyez","by":{"3":"12"}},{"t":"case","label":"Verizon Communications Inc. v. FCC","cite":"535 U.S. 467","y":2002,"id":"2001/00-511","sc":1,"sum":"The Court held that the FCC can require state commissions to set the rates charged by incumbents for leased elements on a forward-looking basis untied to the incumbents' investment and that the FCC can require incumbents to combine elements of their networks at the request of entrants.","sumSrc":"Oyez","by":{"3":"12"}}]};